using Astrea.BattleActions;
using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ReefSongEffect", menuName = "Data/Battle/Effects/Cellarius/ReefSong Effect")]
public class ReefSongEffect : Effect
{
	[Header("Purify Empower")]
	[SerializeField]
	private EmpowerEffect purifyEmpowerEffect;

	[SerializeField]
	private int increaseVirtuesPurificationAmount;

	public int IncreaseVirtuesPurificationAmount => increaseVirtuesPurificationAmount;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, increaseVirtuesPurificationAmount, GetNumberToReplaceWithX());
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), increaseVirtuesPurificationAmount, amount);
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
		{
			PlayerEffects component = effectOwner.GetComponent<PlayerEffects>();
			if (!component.IsEffectActiveWithActivation(purifyEmpowerEffect, activateFeedback: false))
			{
				ToggleActionValueModifierOnRunes(new ActionValueModifier(increaseVirtuesPurificationAmount, BattleActionInteractionEnum.PURIFY), component.RunesPanelReference.value.GetComponent<RunesPanel>());
			}
		});
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		base.RemoveEffect(effectAmount, effectOwner);
		effectOwner.GetComponent<PlayerEffects>().RemoveActionValueModifierFromRunes(purifyEmpowerEffect.BattleActionInteractionEnum);
	}

	public override void OnRemoveEffectEndOfBattle(int effectAmount, GameObject effectOwner)
	{
		RemoveEffect(effectAmount, effectOwner);
	}

	public void ToggleActionValueModifierOnRunes(ActionValueModifier actionValueModifier, RunesPanel runesPanel)
	{
		if (actionValueModifier.BattleActionInteractionEnum == purifyEmpowerEffect.BattleActionInteractionEnum)
		{
			runesPanel.ToggleActionValueModifierCellarius(actionValueModifier);
		}
	}
}
